// ============================================================
// Aggregate GitHub activity data for Claude API prompt
// 
// ============================================================

const commits = $input.all()[0]?.json || [];
const issues = $input.all()[1]?.json || [];
const pulls = $input.all()[2]?.json || [];
const releases = $input.all()[3]?.json || [];

// Get repo info from workflow env
const repoName = $env.REPO_NAME || 'unknown/repo';
const weekStart = new Date(Date.now() - 7 * 86400000).toISOString().split('T')[0];
const weekEnd = new Date().toISOString().split('T')[0];

// Summarize commits
const commitSummary = commits.slice(0, 50).map(c => ({
  sha: c.sha?.substring(0, 7),
  message: c.commit?.message?.split('\n')[0] || 'no message',
  author: c.commit?.author?.name || c.author?.login || 'unknown',
  date: c.commit?.author?.date?.split('T')[0] || 'unknown'
}));

const uniqueAuthors = [...new Set(commitSummary.map(c => c.author))];

// Summarize issues
const closedIssues = issues.filter(i => i.state === 'closed' && i.pull_request === undefined);
const openIssues = issues.filter(i => i.state === 'open' && i.pull_request === undefined);
const newIssues = openIssues.filter(i => new Date(i.created_at) > new Date(Date.now() - 7 * 86400000));

// Summarize PRs
const mergedPRs = pulls.filter(p => p.merged_at);
const closedPRs = pulls.filter(p => !p.merged_at && p.state === 'closed');
const openPRs = pulls.filter(p => p.state === 'open');

// Releases
const latestRelease = releases[0] || null;

const summary = {
  repo: repoName,
  period: `${weekStart} → ${weekEnd}`,
  stats: {
    total_commits: commits.length,
    unique_contributors: uniqueAuthors.length,
    issues_closed: closedIssues.length,
    issues_opened: newIssues.length,
    issues_open: openIssues.length,
    prs_merged: mergedPRs.length,
    prs_closed: closedPRs.length,
    prs_open: openPRs.length,
    latest_release: latestRelease?.tag_name || 'none'
  },
  contributors: uniqueAuthors,
  recent_commits: commitSummary.slice(0, 15),
  closed_issues: closedIssues.slice(0, 10).map(i => ({
    number: i.number,
    title: i.title,
    closed_by: i.closed_by?.login || i.user?.login || 'unknown'
  })),
  merged_prs: mergedPRs.slice(0, 10).map(p => ({
    number: p.number,
    title: p.title,
    author: p.user?.login || 'unknown',
    merged_at: p.merged_at?.split('T')[0]
  })),
  new_issues: newIssues.slice(0, 5).map(i => ({
    number: i.number,
    title: i.title,
    author: i.user?.login || 'unknown',
    labels: (i.labels || []).map(l => l.name)
  })),
  open_prs: openPRs.slice(0, 5).map(p => ({
    number: p.number,
    title: p.title,
    author: p.user?.login || 'unknown'
  }))
};

return summary;

// ============================================================
// Build Claude API prompt from aggregated data
// 
// ============================================================

const data = $input.first().json;

// ─── Multi-language support ──────────────────────────────
const language = $env.SUMMARY_LANG || 'EN';
const langInstructions = {
  'EN': 'Write a narrative-style weekly summary in English.',
  'FR': 'Rédigez un résumé hebdomadaire narratif en français.',
};

const prompt = `You are a developer advocate writing a weekly dev summary for ${data.repo}.

## Repository Activity: ${data.period}

### Stats
- ${data.stats.total_commits} commits by ${data.stats.unique_contributors} contributors
- ${data.stats.issues_closed} issues closed · ${data.stats.issues_opened} new issues
- ${data.stats.prs_merged} PRs merged · ${data.stats.prs_open} open PRs
${data.stats.latest_release !== 'none' ? `- Latest release: ${data.stats.latest_release}` : ''}

### Recent Commits
${data.recent_commits.map(c => `- [${c.sha}] ${c.message} (${c.author})`).join('\n')}

### Merged PRs
${data.merged_prs.map(p => `- #${p.number} ${p.title} (@${p.author}) — merged ${p.merged_at}`).join('\n')}

### Closed Issues
${data.closed_issues.map(i => `- #${i.number} ${i.title}`).join('\n')}

### New Issues
${data.new_issues.map(i => `- #${i.number} ${i.title} [${(i.labels || []).join(', ')}]`).join('\n')}

### Open PRs Needing Review
${data.open_prs.map(p => `- #${p.number} ${p.title} (@${p.author})`).join('\n')}

---
Write a narrative-style weekly summary in Markdown with these sections:

## 🚀 What Shipped
(Highlight merged PRs and releases — what value was delivered?)

## 🔧 What We Fixed
(Significant bug fixes and closed issues)

## 👥 Contributors
(Shout-out to contributors by name — ${data.contributors.join(', ')})

## 📊 By the Numbers
(Stats in a clean table)

## 🔮 What's Next
(Based on open PRs and new issues, what's coming)

**Language Requirement**: ${langInstructions[language] || langInstructions['EN']}

**Tone**: Professional but warm. Engineering audience. 
**Length**: 300-500 words total.`;

return { prompt, repo: data.repo, period: data.period, stats: data.stats };

// ============================================================
// Format Claude API response + assemble final report
// 
// ============================================================

const claudeResponse = $input.first().json;
const summaryData = $('Build Claude Prompt').first().json;

// Extract text from Claude response
const aiContent = claudeResponse.content?.[0]?.text || 
                  claudeResponse.choices?.[0]?.message?.content ||
                  '_(AI summary generation failed)_';

// Assemble final report
const weekStart = summaryData.period?.split(' → ')[0] || 'Unknown';
const weekEnd = summaryData.period?.split(' → ')[1] || 'Unknown';
const repo = summaryData.repo || 'unknown/repo';

const report = `# 📊 Weekly Dev Summary: ${repo}

**${weekStart} → ${weekEnd}**

${aiContent}

---

*Generated by [n8n + Claude Code workflow](https://github.com/claude-builders-bounty) ·  *
`;

return {
  report,
  subject: `📊 [${repo}] Weekly Dev Summary — ${weekStart} to ${weekEnd}`,
  plainText: report.replace(/[#*`>\-\[\]]/g, '').replace(/\n{3,}/g, '\n\n').trim(),
  repo,
  period: summaryData.period
};
